#!/bin/bash
O=spike-owed-d; cd "$O"
H="--add-host perm.nc.test:198.19.60.20 --add-host sub.perm.nc.test:198.19.60.20 --add-host denied.other.test:198.19.60.20 --add-host x.nc.test:198.19.60.20"; URLS="https://perm.nc.test:8441/ https://denied.other.test:8442/ https://sub.perm.nc.test:8443/ https://198.19.60.20:8444/ https://denied.other.test:8445/ https://denied.other.test:8446/ https://perm.nc.test:8447/ https://198.19.60.20:8448/ https://denied.other.test:8449/ https://x.nc.test:8450/"; CAS=/i3/certs/ca-nc.pem:/i3/certs/ca-ncp.pem:/i3/certs/ca-ncdns.pem:/i3/certs/ca-ctl.pem
echo "### Firefox again, reading the error code from the page"; docker run --rm --name od-ff --network od-ca $H -v $O/i3:/i3:ro -e CAS=$CAS od-firefox bash /i3/ff.sh policy $URLS 2>&1; echo "--- NSS"; docker run --rm --name od-ff --network od-ca $H -v $O/i3:/i3:ro -e CAS=$CAS od-firefox bash /i3/ff.sh nss $URLS 2>&1;  echo "--- SSL_CERT_FILE only"; docker run --rm --name od-ff --network od-ca $H -v $O/i3:/i3:ro -e SSL_CERT_FILE=/i3/certs/ca-nc.pem od-firefox bash /i3/ff.sh env https://perm.nc.test:8441/ 2>&1; echo "--- server's view of refused handshakes"; docker logs od-casrv 2>&1 | grep tlserr | sed 's/from [0-9.:]*//; s/[0-9/]* [0-9:]* //' | sort | uniq -c
for V in 8.0 10.0; do echo "--- .NET $V, the handler's defaults, no callback, SSL_CERT_FILE at a bundle"; docker run --rm --name od-dn --network od-ca $H -v $O/i3:/i3:ro -v od-dn$V:/app -e DOTNET_CLI_TELEMETRY_OPTOUT=1 mcr.microsoft.com/dotnet/sdk:$V sh -c "cat /etc/ssl/certs/ca-certificates.crt /i3/certs/ca-nc.pem /i3/certs/ca-ncp.pem /i3/certs/ca-ncdns.pem /i3/certs/ca-ctl.pem > /tmp/bundle.pem; export SSL_CERT_FILE=/tmp/bundle.pem; exec dotnet /app/t.dll default '' $URLS" 2>&1 | cut -c1-330; done
